import { NextResponse } from "next/server";
import { createClient } from "@/utils/supabase/server";
import { contestRegistrationService } from "@/services/auth/contestRegistrationService";

export async function POST(req: Request) {
  try {
    const supabase = await createClient();
    const {
      data: { user },
    } = await supabase.auth.getUser();

    if (!user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { contestId, contestName, entryFee, language } = await req.json();
    if (!contestId || !contestName || entryFee === undefined || !language) {
      return NextResponse.json({ error: "Missing required parameters" }, { status: 400 });
    }

    const result = await contestRegistrationService.checkoutAndRegister(
      user.id,
      contestId,
      contestName,
      entryFee,
      language
    );

    if (!result.success) {
      return NextResponse.json({ error: result.error }, { status: 400 });
    }

    return NextResponse.json(result);
  } catch (err) {
    const errorMsg = err instanceof Error ? err.message : "Unknown error";
    return NextResponse.json({ error: errorMsg }, { status: 500 });
  }
}
